func _run_tests() -> void:
	QuizData.current_topic_title = "Videogiochi"
	var quiz := await instantiate_scene("res://quiz.tscn")
	if not check("quiz_scene", quiz != null, "La scena res://quiz.tscn deve istanziarsi correttamente"):
		return

	var icon_node := find_by_name(quiz, "TopicIcon") as TextureRect
	if not check("icon_node", icon_node != null, "In quiz.tscn deve esistere un TextureRect chiamato TopicIcon"):
		return

	var tex := icon_node.texture as AtlasTexture
	if not check("atlas_texture", tex != null, "TopicIcon.texture deve essere una risorsa AtlasTexture"):
		return

	check("atlas_file", tex.atlas != null and tex.atlas.resource_path.ends_with("tiles.png"), "L'atlas deve puntare a tiles.png")
	check("size_16", tex.region.size == Vector2(16, 16), "La regione ritagliata deve avere dimensioni esattamente di 16x16 pixel (è %.0fx%.0f)" % [tex.region.size.x, tex.region.size.y])
	check("vg_region", tex.region.position == Vector2(48, 0), "Per il tema Videogiochi la regione deve partire da (48, 0), corrispondente alla cella dei mattoni (è a %.0f, %.0f)" % [tex.region.position.x, tex.region.position.y])

	quiz.queue_free()
	await wait_frames(2)

	QuizData.current_topic_title = "Cultura Generale"
	var quiz2 := await instantiate_scene("res://quiz.tscn")
	if not check("quiz2_scene", quiz2 != null, "La scena deve potersi riaprire con un altro tema"):
		return

	var icon_node2 := find_by_name(quiz2, "TopicIcon") as TextureRect
	if not check("icon_node2", icon_node2 != null, "TopicIcon deve esistere anche nella seconda istanza"):
		return

	var tex2 := icon_node2.texture as AtlasTexture
	if not check("atlas_texture2", tex2 != null, "TopicIcon.texture deve essere una AtlasTexture anche per Cultura Generale"):
		return

	check("gen_region", tex2.region.position == Vector2(0, 0), "Per il tema Cultura Generale la regione deve partire da (0, 0), corrispondente alla cella dell'erba (è a %.0f, %.0f)" % [tex2.region.position.x, tex2.region.position.y])
	check("size_16_gen", tex2.region.size == Vector2(16, 16), "La regione ritagliata deve essere esattamente 16x16 pixel anche per Cultura Generale")

