	if not check("script_loaded", grid_script != null, "Lo script res://sheet_grid.gd deve essere presente e senza errori di sintassi"):
		return

	# Test 1: Griglia semplice senza margini ne spaziature
	var simple_grid = grid_script.new(Vector2(16.0, 16.0))
	var rect_0_0 = call_if_exists(simple_grid, "get_cell_rect", [0, 0], Rect2())
	check("simple_0_0", rect_0_0 == Rect2(0.0, 0.0, 16.0, 16.0), "Senza margini ne spaziature, la cella (0, 0) deve essere Rect2(0, 0, 16, 16) (e': %s)" % str(rect_0_0))

	var rect_3_1 = call_if_exists(simple_grid, "get_cell_rect", [3, 1], Rect2())
	check("simple_3_1", rect_3_1 == Rect2(48.0, 16.0, 16.0, 16.0), "La cella (3, 1) su tessere 16x16 deve essere Rect2(48, 16, 16, 16) (e': %s)" % str(rect_3_1))

	# Test 2: Griglia con margine e spaziature
	# cella: 32x48, margine: (10, 20), spaziatura: (4, 8)
	var complex_grid = grid_script.new(Vector2(32.0, 48.0), Vector2(10.0, 20.0), Vector2(4.0, 8.0))
	var c_0_0 = call_if_exists(complex_grid, "get_cell_rect", [0, 0], Rect2())
	check("complex_0_0", c_0_0 == Rect2(10.0, 20.0, 32.0, 48.0), "Con margine (10, 20), la cella (0, 0) deve partire da (10, 20) (e': %s)" % str(c_0_0))

	var c_1_0 = call_if_exists(complex_grid, "get_cell_rect", [1, 0], Rect2())
	check("complex_1_0", c_1_0 == Rect2(46.0, 20.0, 32.0, 48.0), "La cella (1, 0) deve tenere conto della spaziatura: X = 10 + 1*(32+4) = 46 (e': %s)" % str(c_1_0))

	var c_2_3 = call_if_exists(complex_grid, "get_cell_rect", [2, 3], Rect2())
	check("complex_2_3", c_2_3 == Rect2(82.0, 188.0, 32.0, 48.0), "La cella (2, 3) deve risultare in Rect2(82, 188, 32, 48) (e': %s)" % str(c_2_3))

	# Test 3: Creazione di AtlasTexture
	var test_tex: Texture2D = load("res://assets/sprites/tiles.png") as Texture2D
	var atlas_result = call_if_exists(complex_grid, "create_atlas_texture", [test_tex, 2, 3], null)
	if check("atlas_created", atlas_result is AtlasTexture, "create_atlas_texture deve restituire un'istanza di AtlasTexture"):
		var at: AtlasTexture = atlas_result as AtlasTexture
		check("atlas_pointer", at.atlas == test_tex, "La proprieta atlas deve puntare alla texture fornita")
		check("atlas_region", at.region == Rect2(82.0, 188.0, 32.0, 48.0), "La proprieta region deve coincidere con il rettangolo calcolato")

