func _run_tests() -> void:
	var deck_script = load("res://card_deck.gd")
	if not check("deck_script_exists", deck_script != null, "Lo script res://card_deck.gd deve essere presente e valido"):
		return

	var tiles_tex: Texture2D = load("res://assets/sprites/tiles.png") as Texture2D
	if not check("tiles_found", tiles_tex != null, "tiles.png deve essere accessibile in assets/sprites/"):
		return

	# Controllo 1: griglia con margini e spazi arbitrari
	# Carta 30x40, margine (12, 14), spaziatura (6, 8)
	var custom_deck = deck_script.new(tiles_tex, Vector2(30.0, 40.0), Vector2(12.0, 14.0), Vector2(6.0, 8.0))
	var reg_2_1 = call_if_exists(custom_deck, "get_card_region", [2, 1], Rect2())
	# X = 12 + 2*(30+6) = 12 + 72 = 84
	# Y = 14 + 1*(40+8) = 14 + 48 = 62
	check("custom_deck_region", reg_2_1 == Rect2(84.0, 62.0, 30.0, 40.0), "La regione calcolata con margine e spaziatura deve essere Rect2(84, 62, 30, 40) (e': %s)" % str(reg_2_1))

	var card_tex = call_if_exists(custom_deck, "get_card_texture", [2, 1], null)
	if check("custom_card_tex", card_tex is AtlasTexture, "get_card_texture deve restituire un'istanza di AtlasTexture"):
		var at: AtlasTexture = card_tex as AtlasTexture
		check("custom_card_region", at.region == Rect2(84.0, 62.0, 30.0, 40.0), "La texture della carta deve avere la regione corretta")

	# Controllo 2: carte premio in base al punteggio
	var tiles_deck = deck_script.new(tiles_tex, Vector2(16.0, 16.0), Vector2.ZERO, Vector2.ZERO)
	var card_high = call_if_exists(tiles_deck, "get_reward_card", [3], null) as AtlasTexture
	var card_mid = call_if_exists(tiles_deck, "get_reward_card", [1], null) as AtlasTexture
	var card_low = call_if_exists(tiles_deck, "get_reward_card", [0], null) as AtlasTexture

	check("reward_high", card_high != null and card_high.region == Rect2(48.0, 0.0, 16.0, 16.0), "Con punteggio >= 2 la carta premio deve essere la cella (3, 0) Rect2(48, 0, 16, 16)")
	check("reward_mid", card_mid != null and card_mid.region == Rect2(32.0, 0.0, 16.0, 16.0), "Con punteggio == 1 la carta premio deve essere la cella (2, 0) Rect2(32, 0, 16, 16)")
	check("reward_low", card_low != null and card_low.region == Rect2(16.0, 0.0, 16.0, 16.0), "Con punteggio <= 0 la carta premio deve essere la cella (1, 0) Rect2(16, 0, 16, 16)")

	# Controllo 3: integrazione nella scena results.tscn
	QuizData.score = 2
	var results := await instantiate_scene("res://results.tscn")
	if not check("results_loaded", results != null, "La scena res://results.tscn deve istanziarsi senza errori"):
		return

	var reward_node := find_by_name(results, "RewardCard") as TextureRect
	if not check("reward_node", reward_node != null, "In results.tscn deve essere presente il nodo TextureRect chiamato RewardCard"):
		return

	var res_tex := reward_node.texture as AtlasTexture
	if not check("res_tex_atlas", res_tex != null, "RewardCard.texture deve essere una AtlasTexture assegnata a tempo di esecuzione"):
		return

	check("res_tex_region", res_tex.region == Rect2(48.0, 0.0, 16.0, 16.0), "Con QuizData.score = 2, RewardCard deve mostrare la carta (3, 0) Rect2(48, 0, 16, 16)")

